import{_ as o,a as t,c as s,ac as a}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第102–108课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第102–108课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第95–101课","link":"/life/english/new-concept/book-1/review-part-14"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第109–115课","link":"/life/english/new-concept/book-1/review-part-16"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第95–101课","link":"/life/english/new-concept/book-1/review-part-14"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第109–115课","link":"/life/english/new-concept/book-1/review-part-16"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-15.md","filePath":"life/english/new-concept/book-1/review-part-15.md"}'),n={name:"life/english/new-concept/book-1/review-part-15.md"};function r(l,e,i,h,c,p){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第102–108课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第102–108课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第102–108课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第102–108课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-102-·-间接引语中的人称转换" tabindex="-1">Lesson 102 · 间接引语中的人称转换 <a class="header-anchor" href="#lesson-102-·-间接引语中的人称转换" aria-label="Permalink to &quot;Lesson 102 · 间接引语中的人称转换 {#lesson-102-·-间接引语中的人称转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The boys say they will arrive tomorrow.</p><h3 id="练习-1-101" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-101" aria-label="Permalink to &quot;练习 1 {#练习-1-101}&quot;">​</a></h3><p>The boys say, &quot;We will arrive.&quot; 改为间接引语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The boys say they will arrive.</p><p><strong>解析：</strong> 按本课规则判断：把别人第一人称的话转述出来时，应按实际身份转换 I、my、we 等代词，而不是固定一律变 he。主句 says 为现在时，从句可保留原来的时态；说话者的 I 如果指 Rita，转述可用 she。时间地点词是否改变取决于转述发生的时间和地点，不是见到间接引语就机械替换全部词。</p></details><p><strong>表达迁移：</strong> 围绕“转述信件内容并调整人称”写两至三句，再读给同伴听。至少使用一次间接引语中的人称转换，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The boys say they will arrive tomorrow. Rita says she is staying with her aunt.</p><p>The boys say 是复数主语和原形谓语；从句 they will arrive 表将来，tomorrow 按当前转述时间理解。 Rita says 是现在时引述；she 与 her 都指 Rita，is staying 描述她现阶段的居住安排。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-102">回看本课</a></p><h2 id="lesson-103-·-too-very-enough" tabindex="-1">Lesson 103 · too/very/enough <a class="header-anchor" href="#lesson-103-·-too-very-enough" aria-label="Permalink to &quot;Lesson 103 · too/very/enough {#lesson-103-·-too-very-enough}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The instructions are clear enough to follow.</p><h3 id="练习-1-102" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-102" aria-label="Permalink to &quot;练习 1 {#练习-1-102}&quot;">​</a></h3><p>排序：clear / enough.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> clear enough</p><p><strong>解析：</strong> 按本课规则判断：very 只是加强程度，too 通常表示超过合适范围、带来困难；enough 表足够。enough 修饰形容词或副词时放后面，如 easy enough；修饰名词时放前面，如 enough time。too ... to ... 表太……而不能，形容词或副词后接不定式说明结果。不要把 very difficult 误解为一定无法完成。</p></details><p><strong>表达迁移：</strong> 围绕“评价难度和完成任务的能力”写两至三句，再读给同伴听。至少使用一次too/very/enough，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The instructions are clear enough to follow. This suitcase is too heavy for me to lift.</p><p>Clear 是表语，enough 放在形容词之后；to follow 说明足够清楚所能完成的活动。 Too heavy 表超过能力范围；for me 指动作执行者，to lift 给出因太重而无法完成的动作。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-103">回看本课</a></p><h2 id="lesson-104-·-too-very-enough" tabindex="-1">Lesson 104 · too/very/enough <a class="header-anchor" href="#lesson-104-·-too-very-enough" aria-label="Permalink to &quot;Lesson 104 · too/very/enough {#lesson-104-·-too-very-enough}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This suitcase is too heavy for me to lift.</p><h3 id="练习-1-103" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-103" aria-label="Permalink to &quot;练习 1 {#练习-1-103}&quot;">​</a></h3><p>选择 very/too：箱子重得提不起，It is ___ heavy to lift.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> too</p><p><strong>解析：</strong> 按本课规则判断：very 只是加强程度，too 通常表示超过合适范围、带来困难；enough 表足够。enough 修饰形容词或副词时放后面，如 easy enough；修饰名词时放前面，如 enough time。too ... to ... 表太……而不能，形容词或副词后接不定式说明结果。不要把 very difficult 误解为一定无法完成。</p></details><p><strong>表达迁移：</strong> 围绕“评价难度和完成任务的能力”写两至三句，再读给同伴听。至少使用一次too/very/enough，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This suitcase is too heavy for me to lift. The instructions are clear enough to follow.</p><p>Too heavy 表超过能力范围；for me 指动作执行者，to lift 给出因太重而无法完成的动作。 Clear 是表语，enough 放在形容词之后；to follow 说明足够清楚所能完成的活动。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-104">回看本课</a></p><h2 id="lesson-105-·-动词-宾语-to-do" tabindex="-1">Lesson 105 · 动词 + 宾语 + to do <a class="header-anchor" href="#lesson-105-·-动词-宾语-to-do" aria-label="Permalink to &quot;Lesson 105 · 动词 + 宾语 + to do {#lesson-105-·-动词-宾语-to-do}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Please ask Leo to check the figures.</p><h3 id="练习-1-104" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-104" aria-label="Permalink to &quot;练习 1 {#练习-1-104}&quot;">​</a></h3><p>补小词：Ask Leo ___ check the figures.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> 按本课规则判断：want、ask、tell 等动词可接宾语和不定式，表示希望或要求某人做某事：ask someone to check。宾语代词用 me/him/her/us/them，不用主格。否定不定式在 to 前加 not，如 tell him not to wait。want to do 是自己想做，want someone to do 是想让别人做，动作执行者不同。</p></details><p><strong>表达迁移：</strong> 围绕“提出要求并纠正文稿”写两至三句，再读给同伴听。至少使用一次动词 + 宾语 + to do，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Please ask Leo to check the figures. I told her not to send the draft yet.</p><p>Ask 为祈使句谓语，Leo 为宾语，to check 为宾语补足语；实际执行 check 的人是 Leo。 Told 为过去式，her 为宾语；not to send 是否定不定式，yet 表暂时仍不要发送。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-105">回看本课</a></p><h2 id="lesson-106-·-动词-宾语-to-do" tabindex="-1">Lesson 106 · 动词 + 宾语 + to do <a class="header-anchor" href="#lesson-106-·-动词-宾语-to-do" aria-label="Permalink to &quot;Lesson 106 · 动词 + 宾语 + to do {#lesson-106-·-动词-宾语-to-do}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I told her not to send the draft yet.</p><h3 id="练习-1-105" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-105" aria-label="Permalink to &quot;练习 1 {#练习-1-105}&quot;">​</a></h3><p>补宾格：I told ___ (she) not to send it.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> her</p><p><strong>解析：</strong> 按本课规则判断：want、ask、tell 等动词可接宾语和不定式，表示希望或要求某人做某事：ask someone to check。宾语代词用 me/him/her/us/them，不用主格。否定不定式在 to 前加 not，如 tell him not to wait。want to do 是自己想做，want someone to do 是想让别人做，动作执行者不同。</p></details><p><strong>表达迁移：</strong> 围绕“提出要求并纠正文稿”写两至三句，再读给同伴听。至少使用一次动词 + 宾语 + to do，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I told her not to send the draft yet. Please ask Leo to check the figures.</p><p>Told 为过去式，her 为宾语；not to send 是否定不定式，yet 表暂时仍不要发送。 Ask 为祈使句谓语，Leo 为宾语，to check 为宾语补足语；实际执行 check 的人是 Leo。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-106">回看本课</a></p><h2 id="lesson-107-·-形容词比较级" tabindex="-1">Lesson 107 · 形容词比较级 <a class="header-anchor" href="#lesson-107-·-形容词比较级" aria-label="Permalink to &quot;Lesson 107 · 形容词比较级 {#lesson-107-·-形容词比较级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This backpack is lighter than that one.</p><h3 id="练习-1-106" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-106" aria-label="Permalink to &quot;练习 1 {#练习-1-106}&quot;">​</a></h3><p>写比较级：light → ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> lighter</p><p><strong>解析：</strong> 按本课规则判断：比较两者时常用形容词比较级 + than。短形容词常加 er，如 tall→taller；辅音加 y 结尾通常变 y 为 i 再加 er，如 heavy→heavier；多音节形容词常用 more。than 后的比较对象应同类，例如 this bag 与 that one。不能同时使用 more 和 heavier。</p></details><p><strong>表达迁移：</strong> 围绕“比较两个物品的尺寸和价格”写两至三句，再读给同伴听。至少使用一次形容词比较级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This backpack is lighter than that one. The blue jacket is more expensive than the grey one.</p><p>Lighter 是 light 的比较级；than that one 引出同类比较对象，one 替代 backpack。 More expensive 是多音节形容词比较级；the grey one 替代 the grey jacket，避免重复名词。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-107">回看本课</a></p><h2 id="lesson-108-·-形容词比较级" tabindex="-1">Lesson 108 · 形容词比较级 <a class="header-anchor" href="#lesson-108-·-形容词比较级" aria-label="Permalink to &quot;Lesson 108 · 形容词比较级 {#lesson-108-·-形容词比较级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The blue jacket is more expensive than the grey one.</p><h3 id="练习-1-107" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-107" aria-label="Permalink to &quot;练习 1 {#练习-1-107}&quot;">​</a></h3><p>写比较级：expensive → ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> more expensive</p><p><strong>解析：</strong> 按本课规则判断：比较两者时常用形容词比较级 + than。短形容词常加 er，如 tall→taller；辅音加 y 结尾通常变 y 为 i 再加 er，如 heavy→heavier；多音节形容词常用 more。than 后的比较对象应同类，例如 this bag 与 that one。不能同时使用 more 和 heavier。</p></details><p><strong>表达迁移：</strong> 围绕“比较两个物品的尺寸和价格”写两至三句，再读给同伴听。至少使用一次形容词比较级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The blue jacket is more expensive than the grey one. This backpack is lighter than that one.</p><p>More expensive 是多音节形容词比较级；the grey one 替代 the grey jacket，避免重复名词。 Lighter 是 light 的比较级；than that one 引出同类比较对象，one 替代 backpack。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-108">回看本课</a></p>',60)])])}const u=o(n,[["render",r]]);export{d as __pageData,u as default};
